using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF 9 removed HasIndex for Cosmos (never had effect).
            // Removed: entity.HasIndex(b => b.Name);

            // Breaking change 2: EF 9 renamed the discriminator property from
            // "Discriminator" to "$type". Keep the old name for existing documents.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change 3: EF 9 changed the id format from "EntityType|Key"
            // to just the key value. Preserve the old format for existing documents.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .ToJsonProperty("id")
                .HasValueGenerator<LegacyCosmosIdGenerator>();
        });
    }
}

// Preserves the "Blog|{key}" id format used by EF Core 8
class LegacyCosmosIdGenerator : Microsoft.EntityFrameworkCore.ValueGeneration.ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(Microsoft.EntityFrameworkCore.ChangeTracking.EntityEntry entry)
        => $"Blog|{Guid.NewGuid()}";
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

