class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change 4: EF 9 uses sync-over-async for Cosmos operations.
        // SaveChanges() now throws by default. Use async methods instead.
        RunAsync(context).GetAwaiter().GetResult();
    }

    async Task RunAsync(BlogContext context)
    {
        var blogs = await context.Blogs.ToListAsync();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        await context.SaveChangesAsync();
    }
}

// Breaking change 5: Raw SQL queries referencing "Discriminator" must be updated
// OR the discriminator property name must be preserved (done in BlogContext above).
// If you use raw SQL like:
//   SELECT * FROM c WHERE c.Discriminator = 'Blog'
// This will continue to work because we configured HasDiscriminator("Discriminator").
// Without that fix, EF 9 would expect: c["$type"] = 'Blog'

